#include <iostream>
#include <string>
#include <array>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;

int main() {
    string s;
    cin >> s;

    array<cpp_int, 10> counts{};
    for (auto& count : counts)
        count = 1;

    size_t pk = 1;

    for (size_t i = 1; i < s.size(); ++i) {
        array<cpp_int, 10> next{};
        int digit = s[i] - '0';

        for (int t = 0; t <= 9; ++t) {
            if (counts[t] == 0)
                continue;

            int sum = t + digit;
            int low = sum / 2;
            next[low] += counts[t];

            if (t + '0' == s[i - 1] && low + '0' == s[i] && pk == i)
                ++pk;

            if (sum % 2 == 1) {
                int high = low + 1;
                next[high] += counts[t];

                if (t + '0' == s[i - 1] && high + '0' == s[i] && pk == i)
                    ++pk;
            }
        }

        counts = next;
    }

    cpp_int answer = 0;
    for (const auto& count : counts)
        answer += count;

    if (pk == s.size())
        --answer;

    cout << answer;
    return 0;
}

