int main() {
    string s;
    cin >> s;

    array<cpp_int, 10> counts{};
    for (int digit = 0; digit <= 9; ++digit)
        counts[digit] = 1;

    size_t pk = 1;

    for (size_t i = 1; i < s.size(); ++i) {
        int digit = s[i] - '0';
        array<cpp_int, 10> next{};

        for (int t = 0; t <= 9; ++t) {
            int sum = t + digit;
            next[sum / 2] += counts[t];
            if (sum % 2)
                next[sum / 2 + 1] += counts[t];
        }

        if (pk == i) {
            int previous = s[i - 1] - '0';
            int sum = previous + digit;
            if (sum / 2 == digit ||
                (sum % 2 && sum / 2 + 1 == digit)) {
                ++pk;
            }
        }

        counts = std::move(next);
    }

    cpp_int total = 0;
    for (const cpp_int& count : counts)
        total += count;

    if (pk == s.size())
        --total;

    cout << total;
    return 0;
}

