using namespace std;
using boost::multiprecision::cpp_int;

int main() {
    string s;
    if (!(cin >> s)) return 0;

    array<cpp_int, 10> dp{}, next{};
    for (int digit = 0; digit <= 9; ++digit)
        dp[digit] = 1;

    size_t pk = 1;

    for (size_t i = 1; i < s.size(); ++i) {
        next.fill(0);
        int current = s[i] - '0';
        int previous = s[i - 1] - '0';

        for (int digit = 0; digit <= 9; ++digit) {
            int sum = digit + current;
            int lower = sum / 2;

            next[lower] += dp[digit];
            if (digit == previous && lower == current && pk == i)
                ++pk;

            if (sum % 2 == 1) {
                next[lower + 1] += dp[digit];
                if (digit == previous && lower + 1 == current && pk == i)
                    ++pk;
            }
        }

        dp = next;
    }

    cpp_int answer = 0;
    for (const cpp_int& count : dp)
        answer += count;

    if (pk == s.size())
        --answer;

    cout << answer;
    return 0;
}

