#include <string>
#include <array>
#include <boost/multiprecision/cpp_int.hpp>

using namespace std;
using boost::multiprecision::cpp_int;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    array<cpp_int, 10> dp{}, next{};
    for (auto &x : dp) x = 1;

    bool originalIncluded = true;

    for (size_t i = 1; i < s.size(); ++i) {
        next.fill(0);
        int digit = s[i] - '0';

        for (int t = 0; t <= 9; ++t) {
            int sum = t + digit;
            next[sum / 2] += dp[t];
            if (sum % 2)
                next[sum / 2 + 1] += dp[t];
        }

        if (originalIncluded) {
            int sum = (s[i - 1] - '0') + digit;
            originalIncluded =
                sum / 2 == digit ||
                (sum % 2 && sum / 2 + 1 == digit);
        }

        dp = next;
    }

    cpp_int answer = 0;
    for (const auto &x : dp) answer += x;

    if (originalIncluded) --answer;
    cout << answer;

    return 0;
}

#include <iostream>
#include <string>
#include <array>
#include <cstdlib>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    array<cpp_int, 10> counts{};
    for (int digit = 0; digit < 10; ++digit)
        counts[digit] = 1;

    bool containsOriginal = true;

    for (size_t i = 1; i < s.size(); ++i) {
        array<cpp_int, 10> next{};
        int digit = s[i] - '0';

        for (int previous = 0; previous < 10; ++previous) {
            int sum = previous + digit;
            next[sum / 2] += counts[previous];
            if (sum % 2 != 0)
                next[sum / 2 + 1] += counts[previous];
        }

        counts = next;

        if (abs((s[i - 1] - '0') - digit) > 1)
            containsOriginal = false;
    }

    cpp_int answer = 0;
    for (const cpp_int& count : counts)
        answer += count;

    if (containsOriginal)
        --answer;

    cout << answer;
    return 0;
}

